  line(ctx, { x: c.x - 5, y: c.y - 6 }, { x: c.x + 5, y: c.y - 6 }, '#a9b0ab', 1);
  line(ctx, { x: c.x - 7, y: c.y - 14 }, { x: c.x + 7, y: c.y - 14 }, '#a9b0ab', .8);
