  });
  $('#catalogClose').onclick = () => $('#catalog').classList.add('hidden');
  $('#sideBtn').onclick = toggleSide;
  $('#sideClose').onclick = () => { $('#sidePanel').classList.add('hidden'); $('#sidePanel').classList.remove('mobile-open'); };
