/* ---------- modern glass interface ---------- */
:root{
  --panel:#f4fffc;
  --panel-glass:rgba(239,252,249,.78);
  --line:rgba(255,255,255,.62);
  --line-strong:rgba(255,255,255,.82);
  --shadow:0 20px 55px rgba(4,38,44,.2),0 3px 12px rgba(4,38,44,.08);
  --shadow-sm:0 10px 28px rgba(4,38,44,.16);
}

#topbar,#timebar,.panel,#rail,#mobilePanelBtn{
  -webkit-backdrop-filter:blur(18px) saturate(155%);
  backdrop-filter:blur(18px) saturate(155%);
}
#topbar{
  overflow:hidden;
  background:linear-gradient(112deg,rgba(5,43,51,.82),rgba(7,91,83,.72));
  border-color:rgba(222,255,249,.24);
  box-shadow:0 18px 48px rgba(2,30,38,.3),inset 0 1px 0 rgba(255,255,255,.24),inset 0 -1px 0 rgba(255,255,255,.05);
  -webkit-backdrop-filter:blur(22px) saturate(165%);
  backdrop-filter:blur(22px) saturate(165%);
}
#topbar::before{
  content:"";position:absolute;inset:0 auto 0 -45%;width:35%;pointer-events:none;
  background:linear-gradient(100deg,transparent,rgba(255,255,255,.1),transparent);
  transform:skewX(-18deg);animation:glassSweep 12s ease-in-out infinite;
}
@keyframes glassSweep{0%,62%{left:-45%;opacity:0}70%{opacity:1}88%,100%{left:120%;opacity:0}}
.brand-mark{box-shadow:inset 0 2px 0 rgba(255,255,255,.65),0 7px 18px rgba(255,176,32,.24)}
.stat{background:rgba(229,255,249,.09);border-color:rgba(226,255,250,.13);box-shadow:inset 0 1px 0 rgba(255,255,255,.08)}
.icon-btn{background:rgba(229,255,249,.1);border-color:rgba(226,255,250,.14);box-shadow:inset 0 1px 0 rgba(255,255,255,.1)}

.panel,#rail{
  background:linear-gradient(145deg,rgba(246,255,252,.84),rgba(222,246,241,.72));
  border:1px solid rgba(255,255,255,.68);
  box-shadow:var(--shadow),inset 0 1px 0 rgba(255,255,255,.72);
}
#rail{background:linear-gradient(155deg,rgba(247,255,253,.82),rgba(218,245,239,.68))}
#catalog,#sidePanel{isolation:isolate}
.catalog-head,.side-head{position:relative}
.eyebrow{color:#168d80}
.rail-btn{transition:background .2s,color .2s,transform .2s,box-shadow .2s}
.rail-btn:hover{transform:translateY(-1px);background:rgba(21,151,135,.1)}
.rail-btn.active{background:linear-gradient(145deg,rgba(24,166,149,.96),rgba(7,99,91,.96));box-shadow:0 9px 20px rgba(7,99,91,.3),inset 0 1px 0 rgba(255,255,255,.3)}
.card{
  background:linear-gradient(155deg,rgba(255,255,255,.96),rgba(234,249,245,.88));
  border-color:rgba(255,255,255,.86);
  box-shadow:0 4px 12px rgba(11,70,69,.06),inset 0 1px 0 rgba(255,255,255,.9);
}
.card:hover{box-shadow:0 12px 24px rgba(9,83,78,.15),inset 0 1px 0 #fff}
.card.active{background:linear-gradient(155deg,#f9fffd,#dcf7ef);box-shadow:0 0 0 2px rgba(14,124,114,.2),0 12px 25px rgba(9,83,78,.14)}
.card-preview{background:radial-gradient(circle at 50% 35%,rgba(255,255,255,.92),rgba(208,239,229,.92))}
