1: @font-face{font-family:"KotaDisplay";src:local("Trebuchet MS"),local("Segoe UI Black");font-weight:800}
2: @font-face{font-family:"KotaBody";src:local("Trebuchet MS"),local("Segoe UI");font-weight:400}
3: 
4: :root{
5:   --ink:#0c3035; --ink-soft:#42646a; --ink-faint:#7b979b;
6:   --teal:#0e7c72; --teal-2:#12a091; --teal-dark:#0a4f4b; --teal-deep:#072f33;
7:   --mint:#d9f3ec; --sun:#ffc64a; --sun-2:#ffb020; --coral:#ff7a59;
8:   --sky:#bfeaf5; --panel:#fffdf8; --panel-glass:rgba(255,253,248,.96);
9:   --line:rgba(9,57,62,.11); --line-strong:rgba(9,57,62,.2);
10:   --shadow:0 14px 40px rgba(3,42,48,.17); --shadow-sm:0 6px 18px rgba(3,42,48,.12);
11:   --r:18px; --r-sm:12px;
12:   --safe-top:env(safe-area-inset-top,0px); --safe-bottom:env(safe-area-inset-bottom,0px);
13: }
14: *{box-sizing:border-box;-webkit-tap-highlight-color:transparent}
15: [hidden]{display:none!important}
16: html,body{margin:0;padding:0;height:100%;overflow:hidden;background:#9ed7e5;color:var(--ink);font-family:"KotaBody","Trebuchet MS","Segoe UI",system-ui,sans-serif}
17: button,input{font:inherit;color:inherit}
18: button{cursor:pointer;border:0;background:none}
19: button:focus-visible,input:focus-visible{outline:3px solid #ffcf5f;outline-offset:2px}
20: #app{position:fixed;inset:0}
21: #scene{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none;cursor:grab}
22: #scene.dragging{cursor:grabbing}
23: #scene.building{cursor:crosshair}
24: 
25: .ic{width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round;flex:none}
26: #hud{position:absolute;inset:0;pointer-events:none;z-index:5}
27: #hud>*{pointer-events:auto}
28: 
29: /* ---------- top bar ---------- */
30: #topbar{
31:   position:absolute;top:calc(10px + var(--safe-top));left:12px;right:12px;height:66px;
32:   display:flex;align-items:center;gap:14px;padding:0 12px 0 14px;border-radius:20px;
33:   background:linear-gradient(120deg,rgba(6,52,57,.96),rgba(9,86,80,.94));
34:   border:1px solid rgba(255,255,255,.13);
35:   box-shadow:0 12px 34px rgba(2,32,38,.3),inset 0 1px 0 rgba(255,255,255,.14);
36:   color:#f7fffd;backdrop-filter:blur(10px);z-index:20;
37: }
38: .brand{display:flex;align-items:center;gap:11px;min-width:190px}
39: .brand-mark{width:42px;height:42px;border-radius:13px;background:linear-gradient(150deg,#ffd76a,#ffb020);color:#5a3600;display:grid;grid-template-columns:1fr 1fr;align-items:center;justify-items:center;font-family:"KotaDisplay",sans-serif;font-weight:900;font-size:17px;letter-spacing:-.08em;box-shadow:inset 0 2px 0 rgba(255,255,255,.55),0 4px 10px rgba(0,0,0,.22);padding:0 4px;transform:rotate(-3deg)}
40: .brand-mark span:first-child{transform:translateY(-3px)}
41: .brand-mark span:last-child{transform:translateY(3px)}
42: .city-name{font-family:"KotaDisplay",sans-serif;font-weight:800;font-size:18px;letter-spacing:.01em;line-height:1.15;max-width:190px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
43: .city-sub{font-size:10.5px;letter-spacing:.04em;color:#a9d9d3;display:flex;gap:7px;align-items:center;margin-top:2px;white-space:nowrap}
44: .city-sub .dot{opacity:.5}
45: .stats{display:flex;align-items:center;gap:6px;flex:1;justify-content:center;flex-wrap:nowrap;overflow:hidden}
46: .stat{display:flex;align-items:center;gap:6px;height:40px;padding:0 10px;border-radius:11px;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.08);font-weight:700;font-size:14px;white-space:nowrap}
47: .stat .ic{width:17px;height:17px;color:#9fded6}
48: .stat small{font-size:10px;color:#9fc8c3;font-weight:600;letter-spacing:.02em}
49: .stat.money .ic{color:var(--sun)}
50: .stat.money span{color:#ffe08a}
51: .stat.money small{color:#9fd0a4}
52: .stat.money small.neg{color:#ff9b86}
53: .stat:nth-child(3) .ic{color:#ffe28a}
54: .stat:nth-child(4) .ic{color:#ffd85e}
55: .stat:nth-child(5) .ic{color:#8fd8ff}
56: .top-actions{display:flex;gap:4px;margin-left:auto}
57: .icon-btn{width:38px;height:38px;border-radius:11px;display:grid;place-items:center;color:inherit;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.09);transition:.15s}
58: .icon-btn:hover{background:rgba(255,255,255,.17);transform:translateY(-1px)}
59: .icon-btn:active{transform:translateY(0) scale(.96)}
60: .icon-btn.ghost{background:transparent;border-color:transparent;color:var(--ink-soft)}
61: .icon-btn.ghost:hover{background:rgba(9,57,62,.07)}
62: #topbar .icon-btn{color:#d9f4ef}
63: #topbar .icon-btn:hover{background:rgba(255,255,255,.18)}
64: 
65: /* ---------- rail ---------- */
66: #rail{
67:   position:absolute;left:14px;top:calc(88px + var(--safe-top));bottom:96px;width:70px;
68:   display:flex;flex-direction:column;gap:6px;padding:8px 7px;border-radius:20px;
69:   background:var(--panel-glass);border:1px solid var(--line);box-shadow:var(--shadow);
70:   backdrop-filter:blur(12px);z-index:12;overflow-y:auto;scrollbar-width:none;
