34:   function tone(freq, dur, type, gain, slide) {
35:     const a = ac(); if (!a) return;
36:     const o = a.createOscillator(), g = a.createGain();
37:     o.type = type || 'sine';
38:     o.frequency.setValueAtTime(freq, a.currentTime);
39:     if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(40, slide), a.currentTime + dur);
40:     g.gain.setValueAtTime(0.0001, a.currentTime);
41:     g.gain.exponentialRampToValueAtTime(gain || .05, a.currentTime + .012);
42:     g.gain.exponentialRampToValueAtTime(.0001, a.currentTime + dur);
43:     o.connect(g); g.connect(a.destination);
44:     o.start(); o.stop(a.currentTime + dur + .02);
45:   }
