138:   function generateMap(seed) {
139:     const rand = rng(seed || Date.now());
140:     const grid = [];
141:     for (let y = 0; y < GRID; y++) for (let x = 0; x < GRID; x++) {
142:       grid.push({ terrain: 'grass', road: false, b: null });
143:     }
144:     const s = { grid };
145:     // main lake (lower-left of map)
146:     const lx = 18.2, ly = 17.4, lr = 2.9;
147:     for (let y = 0; y < GRID; y++) for (let x = 0; x < GRID; x++) {
148:       const d = Math.hypot(x - lx, (y - ly) * 1.2);
149:       if (d < lr + rand() * .55) grid[idx(x, y)].terrain = 'water';
150:       else if (d < lr + 1.05) grid[idx(x, y)].terrain = Math.random() < .6 ? 'sand' : 'grass';
151:     }
152:     // small pond
153:     for (let y = 0; y < GRID; y++) for (let x = 0; x < GRID; x++) {
154:       const d = Math.hypot(x - 3.6, (y - 20.2) * 1.15);
155:       if (d < 1.5 + rand() * .3) grid[idx(x, y)].terrain = 'water';
156:       else if (d < 2.1) grid[idx(x, y)].terrain = 'sand';
157:     }
158:     // scatter nature outside the central clearing
159:     const trees = [];
160:     for (let y = 0; y < GRID; y++) for (let x = 0; x < GRID; x++) {
161:       const t = grid[idx(x, y)];
162:       if (t.terrain !== 'grass') continue;
163:       const dc = Math.hypot(x - 12, y - 12);
164:       const edge = Math.min(x, y, GRID - 1 - x, GRID - 1 - y);
165:       let chance = 0;
166:       if (dc > 7.6) chance = .22;
167:       if (edge < 3) chance += .2;
168:       if (dc > 10) chance += .12;
169:       if (rand() < chance) trees.push({ defId: 'tree', x, y, level: 1, variant: Math.floor(rand() * 3) });
170:       else if (rand() < .018 && dc > 6.5) trees.push({ defId: 'rock', x, y, level: 1 });
171:     }
172:     return { grid, treeSeed: trees };
173:   }
