198:   function addBuilding(defId, x, y, level, opt) {
199:     const def = DEFS[defId]; if (!def) return null;
200:     opt = opt || {};
201:     const b = {
202:       uid: uid(), defId, x, y, w: def.w, h: def.h, level: level || 0,
203:       growth: 0, evo: 0, variant: opt.variant != null ? opt.variant : Math.floor(Math.random() * 6)
204:     };
205:     for (let yy = y; yy < y + def.h; yy++) for (let xx = x; xx < x + def.w; xx++) {
206:       if (!inBounds(xx, yy)) return null;
207:       const t = state.grid[idx(xx, yy)];
208:       t.b = b;
209:     }
210:     state.buildings.push(b);
211:     if (!opt.free) state.money -= def.cost;
212:     return b;
213:   }
214:   function removeBuilding(b, refund) {
215:     if (!b) return;
216:     for (let yy = b.y; yy < b.y + b.h; yy++) for (let xx = b.x; xx < b.x + b.w; xx++) {
217:       if (inBounds(xx, yy) && state.grid[idx(xx, yy)].b === b) state.grid[idx(xx, yy)].b = null;
218:     }
219:     const i = state.buildings.indexOf(b);
220:     if (i >= 0) state.buildings.splice(i, 1);
221:     if (refund) state.money += Math.round(defOf(b).cost * .35);
222:     if (state.selected && state.selected.uid === b.uid) { state.selected = null; hideSelection(); }
223:   }
224:   function roadAccess(b) {
225:     for (let y = b.y; y < b.y + b.h; y++) for (let x = b.x; x < b.x + b.w; x++) {
226:       if (inBounds(x - 1, y) && state.grid[idx(x - 1, y)].road) return true;
227:       if (inBounds(x + 1, y) && state.grid[idx(x + 1, y)].road) return true;
228:       if (inBounds(x, y - 1) && state.grid[idx(x, y - 1)].road) return true;
229:       if (inBounds(x, y + 1) && state.grid[idx(x, y + 1)].road) return true;
230:     }
231:     return false;
232:   }
233:   function canPlace(def, x, y, opts) {
234:     opts = opts || {};
235:     if (!def) return { ok: false, msg: 'Bangunan tidak dikenal.' };
236:     if (x < 0 || y < 0 || x + def.w > state.gridSize || y + def.h > state.gridSize) return { ok: false, msg: 'Di luar batas kota.' };
237:     let wild = false;
238:     for (let yy = y; yy < y + def.h; yy++) for (let xx = x; xx < x + def.w; xx++) {
239:       const t = state.grid[idx(xx, yy)];
240:       if (t.terrain === 'water') return { ok: false, msg: 'Tidak bisa membangun di atas air.' };
241:       if (t.road) return { ok: false, msg: 'Petak sudah dipakai jalan.' };
242:       if (t.b) {
243:         if (def.kind === 'road') return { ok: false, msg: 'Ada bangunan di petak ini.' };
244:         if (t.b.defId === 'tree' || t.b.defId === 'rock') wild = true;
245:         else return { ok: false, msg: 'Petak sudah terisi.' };
246:       }
247:     }
248:     if (wild) return { ok: false, msg: 'Bersihkan pohon/batu dengan alat bongkar dulu.' };
249:     if (def.kind !== 'road' && def.kind !== 'decor') {
250:       let ok = false;
251:       const test = { x, y, w: def.w, h: def.h };
252:       ok = roadAccess(test);
253:       if (!ok) return { ok: false, msg: 'Butuh akses jalan di sebelahnya.' };
254:     }
255:     if (!opts.free && state.money < def.cost) return { ok: false, msg: 'Kas kota tidak cukup.' };
256:     return { ok: true };
257:   }
258:   function placeAt(defId, x, y) {
259:     const def = DEFS[defId];
260:     const chk = canPlace(def, x, y);
261:     if (!chk.ok) { sfx.error(); toast(chk.msg, 'bad', 'info'); return false; }
262:     if (def.kind === 'road') {
263:       const t = state.grid[idx(x, y)];
264:       t.road = true; state.money -= def.cost;
265:       ensureCars();
266:     } else {
267:       addBuilding(defId, x, y, 0);
268:     }
269:     sfx.place();
270:     recalc(); checkUnlocks(); updateHUD(true); renderCatalog();
271:     saveGame(true);
272:     return true;
273:   }
274:   function forcePlace(defId, x, y, level) {
275:     const def = DEFS[defId]; if (!def) return null;
276:     if (def.kind === 'road') {
277:       for (let yy = y; yy < y + def.h; yy++) for (let xx = x; xx < x + def.w; xx++) {
278:         if (inBounds(xx, yy)) {
279:           const t = state.grid[idx(xx, yy)];
280:           if (t.b && !t.b.defId !== 'tree') removeBuilding(t.b, false);
281:           t.b = null; t.road = true;
282:         }
283:       }
284:       return true;
285:     }
286:     for (let yy = y; yy < y + def.h; yy++) for (let xx = x; xx < x + def.w; xx++) {
287:       if (inBounds(xx, yy)) {
288:         const t = state.grid[idx(xx, yy)];
289:         if (t.b) removeBuilding(t.b, false);
290:         t.road = false; t.b = null;
291:       }
292:     }
293:     return addBuilding(defId, x, y, level == null ? 1 : level, { free: true });
294:   }
295:   function bulldozeAt(x, y) {
296:     const t = tileAt(x, y);
297:     if (!t) return;
298:     if (t.b) {
299:       const b = t.b;
300:       const def = defOf(b);
301:       if (def.maint === 0 && def.cost === 0 && b.defId === 'rock') { removeBuilding(b, false); toast('Batu dibersihkan.', 'good', 'check'); }
302:       else {
303:         removeBuilding(b, true);
304:         toast(`${def.name} dibongkar · +${money(Math.round(def.cost * .35))}`, 'info', 'trash');
305:       }
306:       sfx.demolish();
307:     } else if (t.road) {
308:       t.road = false; state.money += Math.round(DEFS.road.cost * .5);
309:       toast('Jalan dibongkar.', 'info', 'trash');
310:       sfx.demolish();
311:     } else { return; }
312:     state.cars = state.cars.filter(c => tileAt(Math.round(c.x), Math.round(c.y))?.road);
313:     recalc(); checkUnlocks(); updateHUD(true); updateSelection(); saveGame(true);
314:   }
