316:   // ---------- cars ----------
317:   function allRoads() {
318:     const list = [];
319:     for (let y = 0; y < state.gridSize; y++) for (let x = 0; x < state.gridSize; x++) if (state.grid[idx(x, y)].road) list.push({ x, y });
320:     return list;
