322:   const CAR_COLORS = ['#e6563d', '#3b8fd4', '#f2c94c', '#4fae62', '#c14b7c', '#f28b3c', '#6b7c8a', '#f7f4ec'];
323:   function newCar(tx, ty) {
324:     const choices = [];
325:     for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
326:       const nx = tx + dx, ny = ty + dy;
327:       if (inBounds(nx, ny) && state.grid[idx(nx, ny)].road) choices.push({ x: nx, y: ny, dx, dy });
328:     }
329:     if (!choices.length) return null;
330:     const c = choices[Math.floor(Math.random() * choices.length)];
331:     return {
332:       x: tx + .5, y: ty + .5, fromX: tx + .5, fromY: ty + .5, toX: c.x + .5, toY: c.y + .5,
333:       t: 0, speed: .45 + Math.random() * .35, color: CAR_COLORS[Math.floor(Math.random() * CAR_COLORS.length)],
334:       dir: c.dx > 0 ? 'x' : c.dx < 0 ? '-x' : c.dy > 0 ? 'y' : '-y', alive: true
335:     };
336:   }
337:   function spawnCars(initial) {
338:     const roads = allRoads();
339:     if (!roads.length) return;
340:     const cap = Math.min(16, Math.floor(roads.length / 2.4));
341:     while (state.cars.length < cap) {
342:       const r = roads[Math.floor(Math.random() * roads.length)];
343:       const c = newCar(r.x, r.y);
344:       if (!c) break;
345:       c.t = initial ? Math.random() : 0;
346:       c.x = lerp(c.fromX, c.toX, c.t); c.y = lerp(c.fromY, c.toY, c.t);
347:       state.cars.push(c);
348:       if (state.cars.length > 40) break;
349:     }
350:   }
351:   function ensureCars() { spawnCars(); }
352:   function updateCars(dt) {
353:     if (!state || !state.cars) return;
354:     for (const c of state.cars) {
355:       if (!c.alive) continue;
356:       c.t += dt * c.speed;
357:       if (c.t >= 1) {
358:         const tx = Math.round(c.toX - .5), ty = Math.round(c.toY - .5);
359:         c.fromX = c.toX; c.fromY = c.toY;
360:         const choices = [];
361:         for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
362:           const nx = tx + dx, ny = ty + dy;
363:           if (inBounds(nx, ny) && state.grid[idx(nx, ny)].road) {
364:             if (dx === -c.dx && dy === -c.dy && choices.length) continue;
365:             choices.push({ x: nx, y: ny, dx, dy });
366:           }
367:         }
368:         if (!choices.length) { c.alive = false; continue; }
369:         const pick = choices[Math.floor(Math.random() * choices.length)];
370:         c.toX = pick.x + .5; c.toY = pick.y + .5;
371:         c.dir = pick.dx > 0 ? 'x' : pick.dx < 0 ? '-x' : pick.dy > 0 ? 'y' : '-y';
372:         c.t = 0;
373:       }
374:       c.x = lerp(c.fromX, c.toX, c.t);
375:       c.y = lerp(c.fromY, c.toY, c.t);
376:     }
377:     state.cars = state.cars.filter(c => c.alive);
378:     const roads = allRoads();
379:     if (state.cars.length < Math.min(14, Math.floor(roads.length / 2.4)) && Math.random() < .02) {
380:       const r = roads[Math.floor(Math.random() * roads.length)];
381:       if (r) { const c = newCar(r.x, r.y); if (c) state.cars.push(c); }
382:     }
383:   }
