385:   // ---------- simulation ----------
386:   function levelVal(def, field, level) {
387:     const arr = def[field];
388:     if (Array.isArray(arr)) return arr[Math.min(level, arr.length - 1)] || 0;
389:     return arr || 0;
390:   }
391:   function zoneArtKind(def) {
392:     return def.kind === 'zone-r' ? 'r' : def.kind === 'zone-c' ? 'c' : 'i';
393:   }
394:   function bCenter(b) { return { x: b.x + b.w / 2, y: b.y + b.h / 2 }; }
395:   function distance(a, b) {
396:     const ca = bCenter(a), cb = bCenter(b);
397:     return Math.hypot(ca.x - cb.x, ca.y - cb.y);
398:   }
399:   function nearbyArt(b, arts, radiusOverride) {
400:     for (const o of state.buildings) {
401:       if (o === b) continue;
402:       const d = defOf(o);
403:       if (!d) continue;
404:       const art = KK.render.artFor(d, o.level);
405:       if (!arts.includes(art)) continue;
406:       const r = radiusOverride || d.radius || 0;
407:       if (distance(b, o) <= r) return true;
408:     }
409:     return false;
410:   }
