412:   function recalc() {
413:     if (!state) return;
414:     let pop = 0, workers = 0, jobs = 0, cJobs = 0, iJobs = 0;
415:     let powerUse = 0, powerCap = 0, waterUse = 0, waterCap = 0, expense = 0;
416:     let roadCount = 0, zoneCount = 0, houses = 0, shops = 0, factories = 0;
417:     let hasPower = false, hasWater = false, hasPark = false, hasSchool = false, hasStadium = false;
418:     const houseList = [], amenities = [], polluters = [];
419:     for (const b of state.buildings) {
420:       const d = defOf(b); if (!d) continue;
421:       expense += d.maint || 0;
422:       if (d.kind === 'zone-r') {
423:         zoneCount++;
424:         if (b.level > 0) {
425:           pop += levelVal(d, 'cap', b.level);
426:           powerUse += levelVal(d, 'powerUse', b.level);
427:           waterUse += levelVal(d, 'waterUse', b.level);
428:           houseList.push(b); houses++;
429:         }
430:       } else if (d.kind === 'zone-c') {
431:         zoneCount++;
432:         if (b.level > 0) {
433:           cJobs += levelVal(d, 'jobs', b.level);
434:           powerUse += levelVal(d, 'powerUse', b.level);
435:           waterUse += levelVal(d, 'waterUse', b.level);
436:           shops++;
437:         }
438:       } else if (d.kind === 'zone-i') {
439:         zoneCount++;
440:         if (b.level > 0) {
441:           iJobs += levelVal(d, 'jobs', b.level);
442:           powerUse += levelVal(d, 'powerUse', b.level);
443:           waterUse += levelVal(d, 'waterUse', b.level);
444:           factories++;
445:           polluters.push(b);
446:         }
447:       } else {
448:         powerUse += d.powerUse || 0;
449:         waterUse += d.waterUse || 0;
450:         powerCap += d.powerSupply || 0;
451:         waterCap += d.waterSupply || 0;
452:         jobs += d.jobs || 0;
453:         if (d.powerSupply) hasPower = true;
454:         if (d.waterSupply) hasWater = true;
455:         if (artOr(defOf(b), b) === 'park' || artOr(defOf(b), b) === 'smallpark') hasPark = true;
456:         if (artOr(defOf(b), b) === 'school') hasSchool = true;
457:         if (artOr(defOf(b), b) === 'stadium') hasStadium = true;
458:       }
459:       if (d.happy && d.radius) amenities.push(b);
460:       if (b.defId === 'solar') hasPower = true;
461:     }
462:     for (let y = 0; y < state.gridSize; y++) for (let x = 0; x < state.gridSize; x++) if (state.grid[idx(x, y)].road) roadCount++;
463:     expense += roadCount * DEFS.road.maint;
464:     for (const pid in state.policies) {
465:       const p = KK.POLICIES.find(x => x.id === pid);
466:       if (p && state.policies[pid]) expense += p.cost;
467:     }
468:     workers = Math.round(pop * .42);
469:     jobs += cJobs + iJobs;
470:     const powered = powerUse <= powerCap;
471:     const watered = waterUse <= waterCap;
472:     const policyHappy = KK.POLICIES.reduce((n, p) => n + (state.policies[p.id] ? p.happiness : 0), 0);
473:     const commerceBonus = KK.POLICIES.reduce((n, p) => n + (state.policies[p.id] ? (p.commerce || 0) : 0), 0);
474:     const taxPenalty = Math.max(0, (state.taxRate || 9) - 10) * 2.5;
475:     const unemployment = workers > jobs ? Math.min(24, (workers - jobs) / Math.max(1, workers) * 30) : 0;
476:     const pollutionPolicy = KK.POLICIES.reduce((n, p) => n + (state.policies[p.id] ? (p.pollution || 0) : 0), 0);
477:     let happyTotal = 0;
478:     for (const h of houseList) {
479:       let bonus = 0;
480:       for (const a of amenities) {
481:         const ad = defOf(a);
482:         if (distance(h, a) <= (ad.radius || 0)) bonus += ad.happy || 0;
483:       }
484:       bonus = Math.min(26, bonus);
485:       let poll = 0;
486:       for (const f of polluters) {
487:         if (distance(h, f) <= (defOf(f).pollutionRadius || 3)) poll += 1.6 + f.level * .5;
488:       }
489:       poll = Math.max(0, Math.min(14, poll) - pollutionPolicy);
490:       let hv = 56 + bonus + policyHappy + state.moodBoost - taxPenalty - unemployment - poll;
491:       if (!powered) hv -= 24;
492:       if (!watered) hv -= 20;
493:       happyTotal += clamp(hv, 0, 100);
494:     }
495:     let happiness;
496:     if (houseList.length) happiness = happyTotal / houseList.length;
497:     else happiness = clamp(62 + policyHappy + state.moodBoost - taxPenalty, 0, 100);
498:     const income = pop * .33 * ((state.taxRate || 9) / 9) + cJobs * .5 * (1 + commerceBonus) + iJobs * .36;
499:     state.population = pop;
500:     state.workers = workers;
501:     state.jobs = jobs;
502:     state.commercialJobs = cJobs;
503:     state.industrialJobs = iJobs;
504:     state.powerUse = Math.round(powerUse * 10) / 10;
505:     state.powerCap = powerCap;
506:     state.waterUse = Math.round(waterUse * 10) / 10;
507:     state.waterCap = waterCap;
508:     state.powered = powered;
509:     state.watered = watered;
510:     state.expense = Math.round(expense * 10) / 10;
511:     state.income = Math.round(income * 10) / 10;
512:     state.net = Math.round((income - expense) * 10) / 10;
513:     state.happiness = Math.round(happiness);
514:     state.roadCount = roadCount;
515:     state.zoneCount = zoneCount;
516:     state.hasPower = hasPower;
517:     state.hasWater = hasWater;
518:     state.hasPark = hasPark;
519:     state.hasSchool = hasSchool;
520:     state.hasStadium = hasStadium;
521:     state.houses = houses; state.shops = shops; state.factories = factories;
522:     state.demandR = clamp(16 + jobs * 1.25 - pop * .38 + (state.happiness < 48 ? -8 : 0), 0, 100);
523:     state.demandC = clamp(8 + pop * .34 - cJobs * .85, 0, 100);
524:     state.demandI = clamp(5 + pop * .18 - iJobs * .45, 0, 100);
525:     state.maxPop = Math.max(state.maxPop, pop);
526:     // economy is deliberately forgiving: never below -2.000
527:     if (state.money < -2000) state.money = -2000;
528:     if (!state.stats) state.stats = {};
529:     state.stats.houses = houses; state.stats.shops = shops; state.stats.factories = factories;
530:   }
