536:   function simulateTick() {
537:     if (!state) return;
538:     state.tick++;
539:     state.hour = (state.hour + .36) % 24;
540:     state.moodBoost *= .966;
541:     if (Math.abs(state.moodBoost) < .05) state.moodBoost = 0;
542:     recalc();
543:     const hasPower = state.powerCap >= state.powerUse;
544:     const hasWater = state.waterCap >= state.waterUse;
545:     let changed = false;
546:     for (const b of state.buildings.slice()) {
547:       const d = defOf(b);
548:       if (!d || !d.kind || !d.kind.startsWith('zone')) continue;
549:       const ok = hasPower && hasWater && roadAccess(b);
550:       if (b.level === 0) {
551:         const kind = zoneArtKind(d);
552:         if (ok && demandFor(kind) > 0 && state.happiness >= 38) {
553:           b.growth += 1 + (state.happiness > 66 ? .5 : 0);
554:           if (b.growth >= 2) { b.level = 1; b.growth = 0; b.evo = 0; changed = true; }
555:         } else b.growth = Math.max(0, b.growth - .5);
556:       } else {
557:         const school = nearbyArt(b, ['school']);
558:         const hospital = nearbyArt(b, ['hospital']);
559:         let maxLv = 3;
560:         if (kindOf(d) === 'r') maxLv = 2 + (school ? 1 : 0) + (hospital ? 1 : 0);
561:         if (b.level < Math.min(d.maxLevel || 3, maxLv) && ok && state.happiness >= 50) {
562:           b.evo += state.happiness >= 68 ? 2 : 1;
563:           const need = [0, 7, 13, 21][b.level] || 99;
564:           if (b.evo >= need) { b.level++; b.evo = 0; changed = true; }
565:         } else if (b.evo > 0) b.evo = Math.max(0, b.evo - 1);
566:       }
567:     }
568:     if (changed) recalc();
569:     state.money += state.income - state.expense;
570:     // resource warnings
571:     if (!state.warned.power && state.powerUse > state.powerCap && state.powerUse > 0) {
572:       toast('Listrik tidak cukup! Bangun pembangkit atau taman surya.', 'bad', 'bolt');
573:       state.warned.power = true;
574:     }
575:     if (state.powerUse <= state.powerCap) state.warned.power = false;
576:     if (!state.warned.water && state.waterUse > state.waterCap && state.waterUse > 0) {
577:       toast('Pasokan air kurang! Bangun menara air tambahan.', 'bad', 'drop');
578:       state.warned.water = true;
579:     }
580:     if (state.waterUse <= state.waterCap) state.warned.water = false;
581:     checkUnlocks();
582:     checkMissions();
583:     // random city event
584:     state.eventTimer = (state.eventTimer || 48) - 1;
585:     if (state.eventTimer <= 0) {
586:       state.eventTimer = 55 + Math.floor(Math.random() * 25);
587:       if (!state.modalPause && state.population >= 20) setTimeout(showRandomEvent, 350);
588:     }
589:     if (state.tick % 2 === 0) spawnCars();
590:     if (state.tick % 20 === 0) saveGame(true);
591:     updateAll();
592:     updateSelection();
593:   }
