808:   function updateMinimap() {
809:     const cv = $('#minimap'); if (!cv || !state) return;
810:     const c = cv.getContext('2d');
811:     const w = cv.width, h = cv.height;
812:     c.clearRect(0, 0, w, h);
813:     c.fillStyle = '#8ccfe0'; c.fillRect(0, 0, w, h);
814:     const size = state.gridSize;
815:     const padX = (w - (Math.min(w, h) - 16)) / 2 + 8;
816:     const padY = (h - (Math.min(w, h) - 16)) / 2 + 8;
817:     const cell = (Math.min(w, h) - 16) / size;
818:     for (let y = 0; y < size; y++) for (let x = 0; x < size; x++) {
819:       const t = state.grid[idx(x, y)];
820:       let col = t.terrain === 'water' ? '#3b93b3' : t.terrain === 'sand' ? '#e6d29c' : '#87c568';
821:       if (t.road) col = '#59626a';
822:       if (t.b) {
823:         const d = defOf(t.b);
824:         if (d.kind === 'zone-r') col = '#3aa96b';
825:         else if (d.kind === 'zone-c') col = '#3b8fd4';
826:         else if (d.kind === 'zone-i') col = '#d9a03c';
827:         else if (d.cat === 'service') col = '#e05a8b';
828:         else if (d.cat === 'fun') col = '#f0a33e';
829:         else if (d.kind === 'decor') col = t.b.defId === 'tree' ? '#4f9b54' : '#7bc46a';
830:         else col = '#6f8f89';
831:       }
832:       c.fillStyle = col;
833:       c.fillRect(padX + x * cell, padY + y * cell, Math.ceil(cell), Math.ceil(cell));
834:     }
835:     // camera marker (approx)
836:     const gx = (cam.x / 32 + cam.y / 16) / 2;
837:     const gy = (cam.y / 16 - cam.x / 32) / 2;
838:     c.strokeStyle = 'rgba(255,255,255,.95)'; c.lineWidth = 2;
839:     c.strokeRect(padX + gx * cell - 8, padY + gy * cell - 8, 16, 16);
840:     c.fillStyle = 'rgba(255,255,255,.9)';
841:     c.beginPath(); c.arc(padX + gx * cell, padY + gy * cell, 2.5, 0, 7); c.fill();
842:     // frame
843:     c.strokeStyle = 'rgba(9,57,62,.15)'; c.lineWidth = 1; c.strokeRect(0, 0, w, h);
844:   }
