153:   function drawTerrain(ctx, world, x, y, tile, time) {
154:     const T = iso(x, y), R = iso(x + 1, y), B = iso(x + 1, y + 1), L = iso(x, y + 1);
155:     const h = hash(x, y);
156:     if (tile.terrain === 'water') {
157:       const base = h > .5 ? '#3d9fc0' : '#429fbe';
158:       poly(ctx, [T, R, B, L], base);
159:       const shimmer = (Math.sin(time * 1.1 + x * 1.7 + y * 2.3) + 1) / 2;
160:       ctx.globalAlpha = .18 + shimmer * .18;
161:       line(ctx, { x: T.x + 16, y: T.y + 10 }, { x: T.x + 25, y: T.y + 14.5 }, '#e9ffff', 1.4);
162:       line(ctx, { x: T.x + 9, y: T.y + 20 }, { x: T.x + 17, y: T.y + 24 }, '#d8fbff', 1.2);
163:       line(ctx, { x: T.x + 27, y: T.y + 21 }, { x: T.x + 35, y: T.y + 25 }, '#d8fbff', 1.1);
164:       ctx.globalAlpha = 1;
