166:       const foam = (dir) => {
167:         const n = neighbor(world, x, y, dir);
168:         if (!n || n.terrain === 'water') return;
169:         if (dir === 'n') line(ctx, T, R, 'rgba(240,255,255,.6)', 2.2);
170:         if (dir === 'e') line(ctx, R, B, 'rgba(240,255,255,.55)', 2);
171:         if (dir === 's') line(ctx, B, L, 'rgba(240,255,255,.55)', 1.8);
172:         if (dir === 'w') line(ctx, L, T, 'rgba(240,255,255,.6)', 2);
173:       };
174:       foam('n'); foam('e'); foam('s'); foam('w');
175:       return;
176:     }
177:     let base;
178:     if (tile.terrain === 'sand') base = SAND[Math.floor(h * SAND.length)];
179:     else base = GRASS[Math.floor(h * GRASS.length)];
180:     poly(ctx, [T, R, B, L], base);
181:     if (tile.terrain === 'grass') {
182:       ctx.strokeStyle = 'rgba(45,100,40,.055)'; ctx.lineWidth = .8;
183:       ctx.stroke();
184:       if (h > .32) {
185:         const gx = T.x + 10 + hash(x + 3, y) * 30;
186:         const gy = T.y + 9 + hash(x, y + 5) * 12;
