223:     poly(ctx, [T, R, B, L], col);
224:     // curb / sidewalk on exposed edges
225:     const insetPt = p => ({ x: lerp(p.x, C.x, .14), y: lerp(p.y, C.y, .14) });
226:     const edges = [
227:       ['n', T, R], ['e', R, B], ['s', B, L], ['w', L, T]
228:     ];
229:     for (const [dir, a, b] of edges) {
230:       const n = neighbor(world, x, y, dir);
