245:     const dirs = [
246:       ['n', { x: (T.x + R.x) / 2, y: (T.y + R.y) / 2 }],
247:       ['e', { x: (R.x + B.x) / 2, y: (R.y + B.y) / 2 }],
248:       ['s', { x: (B.x + L.x) / 2, y: (B.y + L.y) / 2 }],
249:       ['w', { x: (T.x + L.x) / 2, y: (T.y + L.y) / 2 }]
250:     ];
251:     let connections = 0;
252:     for (const [dir, mid] of dirs) {
253:       if (neighbor(world, x, y, dir)?.road) {
254:         connections++;
255:         line(ctx, C, mid, 'rgba(247,239,209,.72)', 1.5, [5, 5]);
256:       }
257:     }
258:     if (connections >= 3) {
259:       ctx.globalAlpha = .5;
260:       for (let i = 0; i < 4; i++) {
261:         const a = (i / 4) * Math.PI * 2 + Math.PI / 4;
262:         line(ctx, { x: C.x + Math.cos(a) * 5, y: C.y + Math.sin(a) * 3 }, { x: C.x + Math.cos(a) * 8, y: C.y + Math.sin(a) * 5 }, '#fff', 1.6);
263:       }
264:       ctx.globalAlpha = 1;
265:     }
266:     // pebbles
267:     ctx.globalAlpha = .15;
268:     ctx.fillStyle = '#e8e2d2';
269:     for (let i = 0; i < 2; i++) {
270:       const px = T.x + 12 + hash(x + i, y) * 34, py = T.y + 12 + hash(x, y + i) * 14;
271:       ctx.beginPath(); ctx.arc(px, py, .8, 0, 7); ctx.fill();
272:     }
273:     ctx.globalAlpha = 1;
274:   }
