308:     const over = o.over || 0;
309:     if (over) {
310:       const dirs = [[T, R], [R, B], [B, L], [L, T]];
311:       for (const [a, b] of dirs) {
312:         const na = { x: a.x + (a.x - cx) * .06, y: a.y + (a.y - cy) * .06 };
313:         const nb = { x: b.x + (b.x - cx) * .06, y: b.y + (b.y - cy) * .06 };
