333:   function drawWindows(ctx, faceA, faceB, height, rows, cols, opt) {
334:     const o = opt || {};
335:     const top = o.top || 6, bottom = o.bottom || 7;
336:     const usable = height - top - bottom;
337:     if (usable < 6) return;
338:     const winH = Math.min(o.winH || 6, usable / rows * .5);
339:     const winW = o.winW || 4.6;
340:     const col = NIGHT > .28 ? '#ffd98a' : (o.color || '#bfe6f5');
341:     const frame = o.frame || 'rgba(255,255,255,.28)';
342:     const stepX = (faceB.x - faceA.x) / cols;
343:     const stepY = (faceB.y - faceA.y) / cols;
344:     for (let r = 0; r < rows; r++) {
345:       const wy = height - top - (usable / rows) * (r + .5);
346:       for (let c = 0; c < cols; c++) {
347:         const cx = faceA.x + stepX * (c + .5);
348:         const cy = faceA.y + stepY * (c + .5) - wy;
349:         const ex = (stepX / Math.abs(stepX || 1)) * winW;
350:         ctx.beginPath();
351:         ctx.moveTo(cx - ex / 2, cy);
352:         ctx.lineTo(cx + ex / 2, cy);
353:         ctx.lineTo(cx + ex / 2, cy + winH);
354:         ctx.lineTo(cx - ex / 2, cy + winH);
355:         ctx.closePath();
356:         ctx.fillStyle = col; ctx.fill();
357:         if (o.frame !== false) {
358:           ctx.strokeStyle = frame; ctx.lineWidth = .5; ctx.stroke();
359:         }
360:         if (NIGHT > .28) {
361:           ctx.globalAlpha = .18;
362:           ctx.fillStyle = '#ffe7a8';
363:           ctx.fillRect(cx - ex / 2 - 1, cy - 1, Math.abs(ex) + 2, winH + 2);
364:           ctx.globalAlpha = 1;
365:         }
366:       }
367:     }
