import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const out = '/tmp/opencode/glass-qa-game'; mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ ...config.browser.launchOptions });
for (const [name, width, height] of [['desktop', 1440, 900], ['mobile', 390, 844]]) {
  const page = await browser.newPage({ viewport: { width, height }, deviceScaleFactor: 1, isMobile: name === 'mobile', hasTouch: name === 'mobile' });
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load' });
  await page.locator('#newGameBtn').click();
  await page.waitForTimeout(1200);
  await page.screenshot({ path: `${out}/game-${name}.png` });
  const result = await page.evaluate(() => {
    const rect = s => { const e = document.querySelector(s); const r = e?.getBoundingClientRect(); return r && { x:r.x,y:r.y,w:r.width,h:r.height, visible:!!(r.width && r.height) }; };
    return { title: document.querySelector('#cityNameLabel')?.textContent, grid: document.querySelector('#miniBadge')?.textContent, startHidden: getComputedStyle(document.querySelector('#startScreen')).display === 'none', viewport: [innerWidth,innerHeight], panels: Object.fromEntries(['#topbar','#rail','#catalog','#sidePanel','#timebar','#mobilePanelBtn'].map(s => [s, rect(s)])), bodyScroll: [document.documentElement.scrollWidth, document.documentElement.scrollHeight] };
  });
  if (name === 'mobile') {
    await page.locator('#mobilePanelBtn').click().catch(()=>{});
    await page.waitForTimeout(250);
    await page.screenshot({ path: `${out}/game-mobile-panel.png` });
    result.mobilePanelShown = await page.locator('#sidePanel').evaluate(e => getComputedStyle(e).display !== 'none' && e.getBoundingClientRect().width > 0);
  }
  console.log(JSON.stringify({ name, result, errors }));
  await page.close();
}
await browser.close();

