import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const out = '/tmp/opencode/glass-qa-game'; mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ ...config.browser.launchOptions });
for (const [name, width, height] of [['desktop', 1440, 900], ['mobile', 390, 844]]) {
  const page = await browser.newPage({ viewport: { width, height }, deviceScaleFactor: 1, isMobile: name === 'mobile', hasTouch: name === 'mobile' });
  const errors = []; page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load' }); await page.locator('#newGameBtn').click(); await page.waitForTimeout(300);
  const cats = await page.locator('#rail [data-cat]').evaluateAll(es => es.map(e => ({ id:e.dataset.cat, label:e.getAttribute('aria-label'), box:(()=>{const r=e.getBoundingClientRect();return {x:r.x,y:r.y,w:r.width,h:r.height}})() })));
  const categoryResults=[];
  for (const cat of cats) {
    await page.locator(`#rail [data-cat="${cat.id}"]`).click(); await page.waitForTimeout(100);
    const details=await page.evaluate(() => {
      const panel=document.querySelector('#catalog'), grid=document.querySelector('#catalogGrid'), r=panel.getBoundingClientRect(), gr=grid.getBoundingClientRect();
      const cards=[...grid.querySelectorAll('.card')].map(e=>{const b=e.getBoundingClientRect();return {name:e.getAttribute('aria-label'),x:b.x,y:b.y,w:b.width,h:b.height,visible:b.width>0&&b.height>0,locked:e.classList.contains('locked')}});
      return { title:document.querySelector('#catalogTitle').textContent, panel:{x:r.x,y:r.y,w:r.width,h:r.height,bottom:r.bottom}, grid:{x:gr.x,y:gr.y,w:gr.width,h:gr.height,bottom:gr.bottom,scrollHeight:grid.scrollHeight,clientHeight:grid.clientHeight,overflowY:getComputedStyle(grid).overflowY}, cards, foot:document.querySelector('#toolHint').textContent, inner:[innerWidth,innerHeight], pageOverflow:[document.documentElement.scrollWidth,document.documentElement.scrollHeight] };
    });
    if(cat.id==='utility') await page.screenshot({path:`${out}/category-${name}.png`});
    const first=await page.locator('#catalogGrid .card:not(.locked):not(.cant)').first();
    let selected=null;
    if(await first.count()) { selected=await first.getAttribute('data-id'); await first.click(); await page.waitForTimeout(100); }
    categoryResults.push({id:cat.id, ...details, selected, activeCount:await page.locator('#catalogGrid .card.active').count()});
  }
  console.log(JSON.stringify({name,cats,categoryResults,errors})); await page.close();
}
await browser.close();

