import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime=join(process.env.HOME,'.local/share/omgithub-playwright');
const require=createRequire(join(runtime,'package.json'));
const {chromium}=require('playwright');
const config=JSON.parse(readFileSync(join(runtime,'linux.json'),'utf8'));
process.env.DISPLAY||=':'+readFileSync(join(runtime,'display'),'utf8').trim();
const browser=await chromium.launch({...config.browser.launchOptions});
for(const width of [320,360,375,390,420]){
 const page=await browser.newPage({viewport:{width,height:844},isMobile:true,hasTouch:true});
 await page.goto('http://127.0.0.1:3002/',{waitUntil:'load'});await page.locator('#newGameBtn').click();
 console.log(JSON.stringify(await page.evaluate(()=>{const q=s=>document.querySelector(s),box=e=>{const r=e.getBoundingClientRect();return {x:r.x,w:r.width,right:r.right,scrollWidth:e.scrollWidth,clientWidth:e.clientWidth,text:e.textContent}};return {width:innerWidth,topbar:box(q('#topbar')),brand:box(q('.brand')),brandText:box(q('.brand-text')),sub:box(q('.city-sub')),mayor:box(q('#mayorLevel')),dot:box(q('.dot')),date:box(q('#dateLabel')),actions:box(q('.top-actions'))}})));
 await page.close();
}
await browser.close();

