const targets = await (await fetch('http://127.0.0.1:9222/json/list')).json();
const target = targets.find(t => t.type === 'page');
if (!target) throw new Error('No Chrome page target');
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
let id = 0;
const pending = new Map();
ws.onmessage = event => {
  const msg = JSON.parse(event.data);
  if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
};
async function cdp(method, params = {}) {
  const requestId = ++id;
  const result = new Promise(resolve => pending.set(requestId, resolve));
  ws.send(JSON.stringify({ id: requestId, method, params }));
  const response = await result;
  if (response.error) throw new Error(JSON.stringify(response.error));
  return response.result;
}
async function evaluate(expression) {
  const { result, exceptionDetails } = await cdp('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
  if (exceptionDetails) throw new Error(exceptionDetails.text + ': ' + (exceptionDetails.exception?.description || ''));
  return result.value;
}
await cdp('Page.enable');
await cdp('Runtime.enable');
await cdp('Emulation.setDeviceMetricsOverride', { width: 1280, height: 800, deviceScaleFactor: 1, mobile: false });
await cdp('Page.navigate', { url: 'http://127.0.0.1:8765/' });
await new Promise(resolve => setTimeout(resolve, 1200));
const result = await evaluate(`(() => {
  const errors = [];
  window.addEventListener('error', e => errors.push(e.message));
  KK.game.startNew('QA Period');
  const g = KK.game, s = g.state;
  s.won = true; s.missionsDone.metro = true;
  const stats = {};
  for (const period of ['day','week','month']) {
    s.period = period; s.elapsedDays = 0; s.tick = 0; s.moodBoost = 10; s.eventTimer = 1000;
    g.recalc();
    const oldMoney = s.money, net = s.income - s.expense, oldBoost = s.moodBoost;
    g.tick(1);
    stats[period] = { dayDelta: s.elapsedDays, number: s.tick, label: document.querySelector('#weekLabel').textContent,
      date: document.querySelector('#dateLabel').textContent, moneyDelta: +(s.money - oldMoney).toFixed(3), expectedMoneyDelta: +(net * ({day:1,week:7,month:30}[period] / 7)).toFixed(3),
      moodRatio: +(s.moodBoost / oldBoost).toFixed(4), eventDelta: +(1000 - s.eventTimer).toFixed(4) };
  }
  s.period = 'month'; s.elapsedDays = 63; s.speed = 3; s.paused = true;
  g.saveGame(true);
  const saved = JSON.parse(localStorage.getItem('kotakita.save.v2'));
  g.loadGame();
  const roundTrip = {period:g.state.period, elapsedDays:g.state.elapsedDays, speed:g.state.speed};
  saved.period = undefined; saved.elapsedDays = undefined; saved.speed = undefined; saved.tick = 10;
  localStorage.setItem('kotakita.save.v2', JSON.stringify(saved)); g.loadGame();
  const migrated = {period:g.state.period, elapsedDays:g.state.elapsedDays, speed:g.state.speed, date: document.querySelector('#dateLabel').textContent};
  const rect = document.querySelector('#timebar').getBoundingClientRect();
  return {stats, roundTrip, migrated, desktopTimebar: {left:rect.left,right:rect.right,width:rect.width,viewport:innerWidth,overflow:rect.left<0||rect.right>innerWidth}, errors};
})()`);
console.log(JSON.stringify(result, null, 2));
await cdp('Emulation.setDeviceMetricsOverride', { width: 360, height: 640, deviceScaleFactor: 1, mobile: true, screenWidth: 360, screenHeight: 640 });
const mobile = await evaluate(`(() => { const r=document.querySelector('#timebar').getBoundingClientRect(); return {rect:{left:r.left,right:r.right,width:r.width,top:r.top,bottom:r.bottom}, viewport:{width:innerWidth,height:innerHeight}, children:[...document.querySelector('#timebar').children].map(e=>({id:e.id||e.className,left:e.getBoundingClientRect().left,right:e.getBoundingClientRect().right,width:e.getBoundingClientRect().width,scroll:e.scrollWidth,client:e.clientWidth})), overflow:r.left<0||r.right>innerWidth}; })()`);
console.log('mobile', JSON.stringify(mobile, null, 2));
ws.close();

