@media(prefers-reduced-motion:reduce){
  #topbar::before,.start-scrim{animation:none}
}

/* ---------- liquid-glass finish ---------- */
#topbar,#timebar,.panel,#rail,#mobilePanelBtn,.modal,.start-content::before{
  -webkit-backdrop-filter:blur(22px) saturate(170%);
  backdrop-filter:blur(22px) saturate(170%);
}
#topbar,#timebar,.panel,#rail,#mobilePanelBtn{
  box-shadow:0 20px 52px rgba(2,34,41,.2),inset 0 1px 0 rgba(255,255,255,.72),inset 0 -1px 0 rgba(255,255,255,.12);
}
#catalog,#sidePanel,#selectionCard{border-color:rgba(255,255,255,.7)}
#catalog,#sidePanel{
  background:linear-gradient(145deg,rgba(248,255,253,.85),rgba(221,246,240,.74));
}
#timebar{
  position:absolute;isolation:isolate;
  background:radial-gradient(ellipse at 18% -50%,rgba(139,255,226,.2),transparent 55%),linear-gradient(120deg,rgba(4,43,51,.88),rgba(6,82,75,.8));
  border-color:rgba(231,255,250,.32);
  box-shadow:0 20px 42px rgba(2,30,38,.3),inset 0 1px 0 rgba(255,255,255,.24),inset 0 -1px 0 rgba(255,255,255,.07);
}
#timebar::before{
  content:"";position:absolute;inset:0;z-index:-1;pointer-events:none;border-radius:inherit;
  background:linear-gradient(110deg,rgba(255,255,255,.09),transparent 38%,rgba(132,245,219,.05) 72%,transparent);
}
.period-control>span{color:rgba(222,255,249,.7)}
#periodSelect{border-color:rgba(226,255,250,.25);background-color:rgba(211,255,246,.13)}
#periodSelect:hover{background-color:rgba(211,255,246,.2)}
#timebar .time-progress{
  position:absolute;left:0;right:0;bottom:0;height:3px;overflow:hidden;
  background:rgba(216,255,246,.1);pointer-events:none;
}
#timebar .time-progress i{
  display:block;width:var(--time-progress,0%);height:100%;border-radius:0 3px 3px 0;
  background:linear-gradient(90deg,#69e6c2,#ffe18a);box-shadow:0 0 10px rgba(105,230,194,.7);
  transition:width .12s linear;
}
#timebar .icon-btn:focus-visible,#speedGroup button:focus-visible,#periodSelect:focus-visible{
  outline:2px solid #ffe18a;outline-offset:2px;
}
#speedGroup button{touch-action:manipulation}
@media(max-width:720px){
  #topbar,#timebar,.panel,#rail,#mobilePanelBtn{-webkit-backdrop-filter:blur(17px) saturate(155%);backdrop-filter:blur(17px) saturate(155%)}
  #timebar{gap:6px;padding:0 8px}
  .period-control>span{font-size:6px}
  #periodSelect{width:78px;padding-left:7px;padding-right:20px}
  .time-info{min-width:0}
  #timebar .time-progress{height:2px}
}
@media(max-width:360px){
  #timebar{gap:4px;padding:0 6px}
  #timebar .icon-btn{width:33px;height:33px}
  #periodSelect{width:72px;font-size:8px}
  .speed-group button{min-width:25px}
  .time-info small{max-width:95px}
}
@supports not ((backdrop-filter:blur(1px)) or (-webkit-backdrop-filter:blur(1px))){
  #catalog,#sidePanel{background:rgba(239,252,249,.97)}
}

