const targets = await (await fetch('http://127.0.0.1:9222/json/list')).json();
const target = targets.find(t => t.type === 'page' && t.url.includes(':8765'));
if (!target) throw new Error('No game page target');
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
let id = 0;
const pending = new Map();
ws.onmessage = event => {
  const msg = JSON.parse(event.data);
  if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
};
async function cdp(method, params = {}) {
  const requestId = ++id;
  const result = new Promise(resolve => pending.set(requestId, resolve));
  ws.send(JSON.stringify({ id: requestId, method, params }));
  const response = await result;
  if (response.error) throw new Error(JSON.stringify(response.error));
  return response.result;
}
async function evaluate(expression) {
  const { result, exceptionDetails } = await cdp('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
  if (exceptionDetails) throw new Error(exceptionDetails.text + ': ' + JSON.stringify(exceptionDetails));
  return result.value;
}
await cdp('Page.enable');
await cdp('Emulation.setDeviceMetricsOverride', { width: 1280, height: 800, deviceScaleFactor: 1, mobile: false });
await cdp('Page.reload', { ignoreCache: true });
await new Promise(resolve => setTimeout(resolve, 1200));
const results = [];
for (const speed of [1, 2, 3]) {
  const before = await evaluate(`(()=>{if(!KK.game.state?.started)KK.game.startNew('QA Pacing');KK.game.state.speed=${speed};KK.game.state.paused=false;KK.game.state.started=true;return {tick:KK.game.state.tick,elapsed:KK.game.state.elapsedDays,started:KK.game.state.started,paused:KK.game.state.paused}})()`);
  await new Promise(resolve => setTimeout(resolve, 6500));
  const after = await evaluate(`(()=>{const s=KK.game.state,e=document.querySelector('#timebar'),r=e.getBoundingClientRect(),fill=e.querySelector('.time-progress i');return {tick:s.tick,elapsed:s.elapsedDays,progress:e.style.getPropertyValue('--time-progress'),fillWidth:getComputedStyle(fill).width,bar:[r.x,r.y,r.width,r.height],scrollWidth:document.documentElement.scrollWidth,innerWidth}})()`);
  results.push({speed,before,after,tickDelta:after.tick-before.tick,elapsedDelta:after.elapsed-before.elapsed});
}
await evaluate(`(()=>{KK.game.state.speed=1;KK.game.state.paused=false;KK.game.state.started=true})()`);
await new Promise(resolve => setTimeout(resolve, 800));
const screenshot = await cdp('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false });
await (await import('node:fs/promises')).writeFile('/tmp/opencode/kk-desktop-running.png', Buffer.from(screenshot.data, 'base64'));
await cdp('Emulation.setDeviceMetricsOverride', { width: 360, height: 640, deviceScaleFactor: 1, mobile: true, screenWidth: 360, screenHeight: 640 });
await new Promise(resolve => setTimeout(resolve, 250));
const mobile = await evaluate(`(()=>{const e=document.querySelector('#timebar'),r=e.getBoundingClientRect();return {bar:[r.x,r.y,r.width,r.height],progress:e.style.getPropertyValue('--time-progress'),overflow:document.documentElement.scrollWidth>innerWidth}})()`);
const mobileShot = await cdp('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false });
await (await import('node:fs/promises')).writeFile('/tmp/opencode/kk-mobile-running.png', Buffer.from(mobileShot.data, 'base64'));
console.log(JSON.stringify({results,mobile}, null, 2));
ws.close();

