242:     }
243:     return false;
244:   }
245:   function canPlace(def, x, y, opts) {
246:     opts = opts || {};
247:     if (!def) return { ok: false, msg: 'Bangunan tidak dikenal.' };
248:     if (x < 0 || y < 0 || x + def.w > state.gridSize || y + def.h > state.gridSize) return { ok: false, msg: 'Di luar batas kota.' };
249:     let wild = false;
250:     for (let yy = y; yy < y + def.h; yy++) for (let xx = x; xx < x + def.w; xx++) {
251:       const t = state.grid[idx(xx, yy)];
252:       if (t.terrain === 'water') return { ok: false, msg: 'Tidak bisa membangun di atas air.' };
253:       if (t.road) return { ok: false, msg: 'Petak sudah dipakai jalan.' };
254:       if (t.b) {
255:         if (def.kind === 'road') return { ok: false, msg: 'Ada bangunan di petak ini.' };
256:         if (t.b.defId === 'tree' || t.b.defId === 'rock') wild = true;
257:         else return { ok: false, msg: 'Petak sudah terisi.' };
258:       }
259:     }
260:     if (wild) return { ok: false, msg: 'Bersihkan pohon/batu dengan alat bongkar dulu.' };
261:     if (def.kind !== 'road' && def.kind !== 'decor') {
262:       let ok = false;
263:       const test = { x, y, w: def.w, h: def.h };
264:       ok = roadAccess(test);
265:       if (!ok) return { ok: false, msg: 'Butuh akses jalan di sebelahnya.' };
266:     }
267:     if (!opts.free && state.money < def.cost) return { ok: false, msg: 'Kas kota tidak cukup.' };
268:     return { ok: true };
269:   }
270:   function placeAt(defId, x, y) {
271:     const def = DEFS[defId];
272:     const chk = canPlace(def, x, y);
273:     if (!chk.ok) { sfx.error(); toast(chk.msg, 'bad', 'info'); return false; }
274:     if (def.kind === 'road') {
275:       const t = state.grid[idx(x, y)];
276:       t.road = true; state.money -= def.cost;
277:       ensureCars();
278:     } else {
279:       addBuilding(defId, x, y, 0);
280:     }
281:     sfx.place();
282:     recalc(); checkUnlocks(); updateHUD(true); renderCatalog();
283:     saveGame(true);
284:     return true;
285:   }
286:   function forcePlace(defId, x, y, level) {
287:     const def = DEFS[defId]; if (!def) return null;
288:     if (def.kind === 'road') {
289:       for (let yy = y; yy < y + def.h; yy++) for (let xx = x; xx < x + def.w; xx++) {
290:         if (inBounds(xx, yy)) {
291:           const t = state.grid[idx(xx, yy)];
292:           if (t.b && !t.b.defId !== 'tree') removeBuilding(t.b, false);
293:           t.b = null; t.road = true;
294:         }
295:       }
296:       return true;
297:     }
298:     for (let yy = y; yy < y + def.h; yy++) for (let xx = x; xx < x + def.w; xx++) {
299:       if (inBounds(xx, yy)) {
300:         const t = state.grid[idx(xx, yy)];
301:         if (t.b) removeBuilding(t.b, false);
302:         t.road = false; t.b = null;
303:       }
304:     }
305:     return addBuilding(defId, x, y, level == null ? 1 : level, { free: true });
306:   }
307:   function bulldozeAt(x, y) {
308:     const t = tileAt(x, y);
309:     if (!t) return;
310:     if (t.b) {
311:       const b = t.b;
312:       const def = defOf(b);
313:       if (def.maint === 0 && def.cost === 0 && b.defId === 'rock') { removeBuilding(b, false); toast('Batu dibersihkan.', 'good', 'check'); }
314:       else {
315:         removeBuilding(b, true);
316:         toast(`${def.name} dibongkar · +${money(Math.round(def.cost * .35))}`, 'info', 'trash');
317:       }
318:       sfx.demolish();
319:     } else if (t.road) {
320:       t.road = false; state.money += Math.round(DEFS.road.cost * .5);
321:       toast('Jalan dibongkar.', 'info', 'trash');
322:       sfx.demolish();
323:     } else { return; }
324:     state.cars = state.cars.filter(c => tileAt(Math.round(c.x), Math.round(c.y))?.road);
325:     recalc(); checkUnlocks(); updateHUD(true); updateSelection(); saveGame(true);
326:   }
