328:   // ---------- cars ----------
329:   function allRoads() {
330:     const list = [];
331:     for (let y = 0; y < state.gridSize; y++) for (let x = 0; x < state.gridSize; x++) if (state.grid[idx(x, y)].road) list.push({ x, y });
332:     return list;
333:   }
334:   const CAR_COLORS = ['#e6563d', '#3b8fd4', '#f2c94c', '#4fae62', '#c14b7c', '#f28b3c', '#6b7c8a', '#f7f4ec'];
335:   function newCar(tx, ty) {
336:     const choices = [];
337:     for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
338:       const nx = tx + dx, ny = ty + dy;
339:       if (inBounds(nx, ny) && state.grid[idx(nx, ny)].road) choices.push({ x: nx, y: ny, dx, dy });
340:     }
341:     if (!choices.length) return null;
342:     const c = choices[Math.floor(Math.random() * choices.length)];
343:     return {
344:       x: tx + .5, y: ty + .5, fromX: tx + .5, fromY: ty + .5, toX: c.x + .5, toY: c.y + .5,
345:       t: 0, speed: .45 + Math.random() * .35, color: CAR_COLORS[Math.floor(Math.random() * CAR_COLORS.length)],
346:       dir: c.dx > 0 ? 'x' : c.dx < 0 ? '-x' : c.dy > 0 ? 'y' : '-y', alive: true
347:     };
348:   }
349:   function spawnCars(initial) {
350:     const roads = allRoads();
351:     if (!roads.length) return;
352:     const cap = Math.min(16, Math.floor(roads.length / 2.4));
353:     while (state.cars.length < cap) {
354:       const r = roads[Math.floor(Math.random() * roads.length)];
355:       const c = newCar(r.x, r.y);
356:       if (!c) break;
357:       c.t = initial ? Math.random() : 0;
358:       c.x = lerp(c.fromX, c.toX, c.t); c.y = lerp(c.fromY, c.toY, c.t);
359:       state.cars.push(c);
360:       if (state.cars.length > 40) break;
361:     }
362:   }
363:   function ensureCars() { spawnCars(); }
364:   function updateCars(dt) {
365:     if (!state || !state.cars) return;
366:     for (const c of state.cars) {
367:       if (!c.alive) continue;
368:       c.t += dt * c.speed;
369:       if (c.t >= 1) {
370:         const tx = Math.round(c.toX - .5), ty = Math.round(c.toY - .5);
371:         c.fromX = c.toX; c.fromY = c.toY;
372:         const choices = [];
373:         for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
374:           const nx = tx + dx, ny = ty + dy;
375:           if (inBounds(nx, ny) && state.grid[idx(nx, ny)].road) {
376:             if (dx === -c.dx && dy === -c.dy && choices.length) continue;
377:             choices.push({ x: nx, y: ny, dx, dy });
378:           }
379:         }
380:         if (!choices.length) { c.alive = false; continue; }
381:         const pick = choices[Math.floor(Math.random() * choices.length)];
382:         c.toX = pick.x + .5; c.toY = pick.y + .5;
383:         c.dir = pick.dx > 0 ? 'x' : pick.dx < 0 ? '-x' : pick.dy > 0 ? 'y' : '-y';
384:         c.t = 0;
385:       }
386:       c.x = lerp(c.fromX, c.toX, c.t);
387:       c.y = lerp(c.fromY, c.toY, c.t);
388:     }
389:     state.cars = state.cars.filter(c => c.alive);
390:     const roads = allRoads();
391:     if (state.cars.length < Math.min(14, Math.floor(roads.length / 2.4)) && Math.random() < .02) {
392:       const r = roads[Math.floor(Math.random() * roads.length)];
393:       if (r) { const c = newCar(r.x, r.y); if (c) state.cars.push(c); }
394:     }
395:   }
