397:   // ---------- simulation ----------
398:   function levelVal(def, field, level) {
399:     const arr = def[field];
400:     if (Array.isArray(arr)) return arr[Math.min(level, arr.length - 1)] || 0;
401:     return arr || 0;
402:   }
403:   function zoneArtKind(def) {
404:     return def.kind === 'zone-r' ? 'r' : def.kind === 'zone-c' ? 'c' : 'i';
405:   }
406:   function bCenter(b) { return { x: b.x + b.w / 2, y: b.y + b.h / 2 }; }
407:   function distance(a, b) {
408:     const ca = bCenter(a), cb = bCenter(b);
409:     return Math.hypot(ca.x - cb.x, ca.y - cb.y);
410:   }
411:   function nearbyArt(b, arts, radiusOverride) {
412:     for (const o of state.buildings) {
413:       if (o === b) continue;
414:       const d = defOf(o);
415:       if (!d) continue;
416:       const art = KK.render.artFor(d, o.level);
417:       if (!arts.includes(art)) continue;
418:       const r = radiusOverride || d.radius || 0;
419:       if (distance(b, o) <= r) return true;
420:     }
421:     return false;
422:   }
423: 
424:   function recalc() {
425:     if (!state) return;
426:     let pop = 0, workers = 0, jobs = 0, cJobs = 0, iJobs = 0;
427:     let powerUse = 0, powerCap = 0, waterUse = 0, waterCap = 0, expense = 0;
428:     let roadCount = 0, zoneCount = 0, houses = 0, shops = 0, factories = 0;
429:     let hasPower = false, hasWater = false, hasPark = false, hasSchool = false, hasStadium = false;
430:     const houseList = [], amenities = [], polluters = [];
431:     for (const b of state.buildings) {
432:       const d = defOf(b); if (!d) continue;
433:       expense += d.maint || 0;
434:       if (d.kind === 'zone-r') {
435:         zoneCount++;
436:         if (b.level > 0) {
437:           pop += levelVal(d, 'cap', b.level);
438:           powerUse += levelVal(d, 'powerUse', b.level);
439:           waterUse += levelVal(d, 'waterUse', b.level);
440:           houseList.push(b); houses++;
441:         }
442:       } else if (d.kind === 'zone-c') {
443:         zoneCount++;
444:         if (b.level > 0) {
445:           cJobs += levelVal(d, 'jobs', b.level);
446:           powerUse += levelVal(d, 'powerUse', b.level);
447:           waterUse += levelVal(d, 'waterUse', b.level);
448:           shops++;
449:         }
450:       } else if (d.kind === 'zone-i') {
451:         zoneCount++;
452:         if (b.level > 0) {
453:           iJobs += levelVal(d, 'jobs', b.level);
454:           powerUse += levelVal(d, 'powerUse', b.level);
455:           waterUse += levelVal(d, 'waterUse', b.level);
456:           factories++;
457:           polluters.push(b);
458:         }
459:       } else {
460:         powerUse += d.powerUse || 0;
461:         waterUse += d.waterUse || 0;
462:         powerCap += d.powerSupply || 0;
463:         waterCap += d.waterSupply || 0;
464:         jobs += d.jobs || 0;
465:         if (d.powerSupply) hasPower = true;
466:         if (d.waterSupply) hasWater = true;
467:         if (artOr(defOf(b), b) === 'park' || artOr(defOf(b), b) === 'smallpark') hasPark = true;
468:         if (artOr(defOf(b), b) === 'school') hasSchool = true;
469:         if (artOr(defOf(b), b) === 'stadium') hasStadium = true;
470:       }
471:       if (d.happy && d.radius) amenities.push(b);
472:       if (b.defId === 'solar') hasPower = true;
473:     }
474:     for (let y = 0; y < state.gridSize; y++) for (let x = 0; x < state.gridSize; x++) if (state.grid[idx(x, y)].road) roadCount++;
475:     expense += roadCount * DEFS.road.maint;
476:     for (const pid in state.policies) {
477:       const p = KK.POLICIES.find(x => x.id === pid);
478:       if (p && state.policies[pid]) expense += p.cost;
479:     }
480:     workers = Math.round(pop * .42);
481:     jobs += cJobs + iJobs;
482:     const powered = powerUse <= powerCap;
483:     const watered = waterUse <= waterCap;
484:     const policyHappy = KK.POLICIES.reduce((n, p) => n + (state.policies[p.id] ? p.happiness : 0), 0);
485:     const commerceBonus = KK.POLICIES.reduce((n, p) => n + (state.policies[p.id] ? (p.commerce || 0) : 0), 0);
486:     const taxPenalty = Math.max(0, (state.taxRate || 9) - 10) * 2.5;
487:     const unemployment = workers > jobs ? Math.min(24, (workers - jobs) / Math.max(1, workers) * 30) : 0;
488:     const pollutionPolicy = KK.POLICIES.reduce((n, p) => n + (state.policies[p.id] ? (p.pollution || 0) : 0), 0);
489:     let happyTotal = 0;
490:     for (const h of houseList) {
491:       let bonus = 0;
492:       for (const a of amenities) {
493:         const ad = defOf(a);
494:         if (distance(h, a) <= (ad.radius || 0)) bonus += ad.happy || 0;
495:       }
496:       bonus = Math.min(26, bonus);
497:       let poll = 0;
498:       for (const f of polluters) {
499:         if (distance(h, f) <= (defOf(f).pollutionRadius || 3)) poll += 1.6 + f.level * .5;
500:       }
501:       poll = Math.max(0, Math.min(14, poll) - pollutionPolicy);
502:       let hv = 56 + bonus + policyHappy + state.moodBoost - taxPenalty - unemployment - poll;
503:       if (!powered) hv -= 24;
504:       if (!watered) hv -= 20;
505:       happyTotal += clamp(hv, 0, 100);
506:     }
507:     let happiness;
508:     if (houseList.length) happiness = happyTotal / houseList.length;
509:     else happiness = clamp(62 + policyHappy + state.moodBoost - taxPenalty, 0, 100);
510:     const income = pop * .33 * ((state.taxRate || 9) / 9) + cJobs * .5 * (1 + commerceBonus) + iJobs * .36;
511:     state.population = pop;
512:     state.workers = workers;
513:     state.jobs = jobs;
514:     state.commercialJobs = cJobs;
515:     state.industrialJobs = iJobs;
516:     state.powerUse = Math.round(powerUse * 10) / 10;
517:     state.powerCap = powerCap;
518:     state.waterUse = Math.round(waterUse * 10) / 10;
519:     state.waterCap = waterCap;
520:     state.powered = powered;
521:     state.watered = watered;
522:     state.expense = Math.round(expense * 10) / 10;
523:     state.income = Math.round(income * 10) / 10;
524:     state.net = Math.round((income - expense) * 10) / 10;
525:     state.happiness = Math.round(happiness);
526:     state.roadCount = roadCount;
527:     state.zoneCount = zoneCount;
528:     state.hasPower = hasPower;
529:     state.hasWater = hasWater;
530:     state.hasPark = hasPark;
531:     state.hasSchool = hasSchool;
532:     state.hasStadium = hasStadium;
533:     state.houses = houses; state.shops = shops; state.factories = factories;
534:     state.demandR = clamp(16 + jobs * 1.25 - pop * .38 + (state.happiness < 48 ? -8 : 0), 0, 100);
535:     state.demandC = clamp(8 + pop * .34 - cJobs * .85, 0, 100);
536:     state.demandI = clamp(5 + pop * .18 - iJobs * .45, 0, 100);
537:     state.maxPop = Math.max(state.maxPop, pop);
538:     // economy is deliberately forgiving: never below -2.000
539:     if (state.money < -2000) state.money = -2000;
540:     if (!state.stats) state.stats = {};
541:     state.stats.houses = houses; state.stats.shops = shops; state.stats.factories = factories;
542:   }
543:   function artOr(def, b) { return KK.render.artFor(def, b.level); }
544:   function demandFor(kind) {
545:     return kind === 'r' ? state.demandR : kind === 'c' ? state.demandC : state.demandI;
546:   }
547: 
548:   function simulateTick() {
549:     if (!state) return;
550:     state.tick++;
551:     const scale = periodScale();
552:     state.elapsedDays = (state.elapsedDays || 0) + PERIOD_DAYS[state.period];
553:     state.hour = (state.hour + .36 * scale) % 24;
554:     state.moodBoost *= Math.pow(.966, scale);
555:     if (Math.abs(state.moodBoost) < .05) state.moodBoost = 0;
556:     recalc();
557:     const hasPower = state.powerCap >= state.powerUse;
558:     const hasWater = state.waterCap >= state.waterUse;
559:     let changed = false;
560:     for (const b of state.buildings.slice()) {
561:       const d = defOf(b);
562:       if (!d || !d.kind || !d.kind.startsWith('zone')) continue;
563:       const ok = hasPower && hasWater && roadAccess(b);
564:       if (b.level === 0) {
565:         const kind = zoneArtKind(d);
566:         if (ok && demandFor(kind) > 0 && state.happiness >= 38) {
567:           b.growth += (1 + (state.happiness > 66 ? .5 : 0)) * scale;
568:           if (b.growth >= 2) { b.level = 1; b.growth = 0; b.evo = 0; changed = true; }
569:         } else b.growth = Math.max(0, b.growth - .5 * scale);
570:       } else {
571:         const school = nearbyArt(b, ['school']);
572:         const hospital = nearbyArt(b, ['hospital']);
573:         let maxLv = 3;
574:         if (kindOf(d) === 'r') maxLv = 2 + (school ? 1 : 0) + (hospital ? 1 : 0);
575:         if (b.level < Math.min(d.maxLevel || 3, maxLv) && ok && state.happiness >= 50) {
576:           b.evo += (state.happiness >= 68 ? 2 : 1) * scale;
577:           const need = [0, 7, 13, 21][b.level] || 99;
578:           if (b.evo >= need) { b.level++; b.evo = 0; changed = true; }
579:         } else if (b.evo > 0) b.evo = Math.max(0, b.evo - scale);
580:       }
581:     }
582:     if (changed) recalc();
583:     state.money += (state.income - state.expense) * scale;
584:     // resource warnings
585:     if (!state.warned.power && state.powerUse > state.powerCap && state.powerUse > 0) {
586:       toast('Listrik tidak cukup! Bangun pembangkit atau taman surya.', 'bad', 'bolt');
587:       state.warned.power = true;
588:     }
589:     if (state.powerUse <= state.powerCap) state.warned.power = false;
590:     if (!state.warned.water && state.waterUse > state.waterCap && state.waterUse > 0) {
591:       toast('Pasokan air kurang! Bangun menara air tambahan.', 'bad', 'drop');
592:       state.warned.water = true;
593:     }
594:     if (state.waterUse <= state.waterCap) state.warned.water = false;
595:     checkUnlocks();
596:     checkMissions();
597:     // random city event
598:     state.eventTimer = (state.eventTimer || 48) - scale;
599:     if (state.eventTimer <= 0) {
600:       state.eventTimer = 55 + Math.floor(Math.random() * 25);
601:       if (!state.modalPause && state.population >= 20) setTimeout(showRandomEvent, 350);
602:     }
603:     if (state.tick % Math.max(1, Math.round(2 / scale)) === 0) spawnCars();
604:     if (state.tick % Math.max(1, Math.round(20 / scale)) === 0) saveGame(true);
605:     updateAll();
606:     updateSelection();
607:   }
608:   function kindOf(def) { return def.kind === 'zone-r' ? 'r' : def.kind === 'zone-c' ? 'c' : 'i'; }
609: 
610:   function checkUnlocks(silent) {
611:     if (!state) return;
612:     for (const id in DEFS) {
613:       const d = DEFS[id];
614:       if (!d.unlockPop || d.unlockPop > state.maxPop) continue;
615:       if (!state.unlocked[id]) {
616:         state.unlocked[id] = true;
617:         if (!silent) {
618:           toast(`Bangunan baru terbuka: ${d.name}`, 'reward', 'trophy');
619:           sfx.unlock();
620:         }
621:       }
622:     }
623:   }
624:   function checkMissions() {
625:     if (!state) return;
626:     for (const m of KK.MISSIONS) {
627:       if (state.missionsDone[m.id]) continue;
628:       if (m.check(state)) {
629:         state.missionsDone[m.id] = true;
630:         state.money += m.reward;
631:         sfx.reward();
632:         toast(`Misi selesai: ${m.label} · +${money(m.reward)}`, 'reward', 'trophy');
633:         if (m.id === 'metro' && !state.won) {
634:           state.won = true;
635:           setTimeout(showWin, 900);
636:         }
637:         updateHUD(true); renderMissions();
638:       }
639:     }
640:   }
