824:   function updateMinimap() {
825:     const cv = $('#minimap'); if (!cv || !state) return;
826:     const c = cv.getContext('2d');
827:     const w = cv.width, h = cv.height;
828:     c.clearRect(0, 0, w, h);
829:     c.fillStyle = '#8ccfe0'; c.fillRect(0, 0, w, h);
830:     const size = state.gridSize;
831:     const padX = (w - (Math.min(w, h) - 16)) / 2 + 8;
832:     const padY = (h - (Math.min(w, h) - 16)) / 2 + 8;
833:     const cell = (Math.min(w, h) - 16) / size;
834:     for (let y = 0; y < size; y++) for (let x = 0; x < size; x++) {
835:       const t = state.grid[idx(x, y)];
836:       let col = t.terrain === 'water' ? '#3b93b3' : t.terrain === 'sand' ? '#e6d29c' : '#87c568';
837:       if (t.road) col = '#59626a';
838:       if (t.b) {
839:         const d = defOf(t.b);
840:         if (d.kind === 'zone-r') col = '#3aa96b';
841:         else if (d.kind === 'zone-c') col = '#3b8fd4';
842:         else if (d.kind === 'zone-i') col = '#d9a03c';
843:         else if (d.cat === 'service') col = '#e05a8b';
844:         else if (d.cat === 'fun') col = '#f0a33e';
845:         else if (d.kind === 'decor') col = t.b.defId === 'tree' ? '#4f9b54' : '#7bc46a';
846:         else col = '#6f8f89';
847:       }
848:       c.fillStyle = col;
849:       c.fillRect(padX + x * cell, padY + y * cell, Math.ceil(cell), Math.ceil(cell));
850:     }
851:     // camera marker (approx)
852:     const gx = (cam.x / 32 + cam.y / 16) / 2;
853:     const gy = (cam.y / 16 - cam.x / 32) / 2;
854:     c.strokeStyle = 'rgba(255,255,255,.95)'; c.lineWidth = 2;
855:     c.strokeRect(padX + gx * cell - 8, padY + gy * cell - 8, 16, 16);
856:     c.fillStyle = 'rgba(255,255,255,.9)';
857:     c.beginPath(); c.arc(padX + gx * cell, padY + gy * cell, 2.5, 0, 7); c.fill();
858:     // frame
859:     c.strokeStyle = 'rgba(9,57,62,.15)'; c.lineWidth = 1; c.strokeRect(0, 0, w, h);
860:   }
