const targets = await (await fetch('http://127.0.0.1:9222/json/list')).json();
const target = targets.find(t => t.type === 'page' && t.url.includes(':8765'));
if (!target) throw new Error('Kota Kita page not found');
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
let id = 0;
const pending = new Map();
ws.onmessage = event => {
  const msg = JSON.parse(event.data);
  if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
};
async function cdp(method, params = {}) {
  const requestId = ++id;
  const result = new Promise(resolve => pending.set(requestId, resolve));
  ws.send(JSON.stringify({ id: requestId, method, params }));
  const response = await result;
  if (response.error) throw new Error(JSON.stringify(response.error));
  return response.result;
}
async function evaluate(expression) {
  const { result, exceptionDetails } = await cdp('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
  if (exceptionDetails) throw new Error(exceptionDetails.text + ': ' + (exceptionDetails.exception?.description || ''));
  return result.value;
}
const before = await evaluate(`(() => {
  KK.game.startNew('Tema QA'); KK.game.state.paused = true; KK.game.render();
  window.__mapBefore = document.querySelector('#scene').getContext('2d').getImageData(0,0,document.querySelector('#scene').width,document.querySelector('#scene').height).data.join(',');
  document.querySelector('#themeBtn').click();
  const canvas = document.querySelector('#scene');
  const mapAfter = canvas.getContext('2d').getImageData(0,0,canvas.width,canvas.height).data.join(',');
  return {theme:document.documentElement.dataset.theme, stored:localStorage.getItem('kotakita.theme.v1'), ariaPressed:document.querySelector('#themeBtn').getAttribute('aria-pressed'), label:document.querySelector('#themeBtn').getAttribute('aria-label'), bodyBackground:getComputedStyle(document.body).backgroundColor, timebarBackground:getComputedStyle(document.querySelector('#timebar')).backgroundImage, mapUnchanged:window.__mapBefore===mapAfter, cssRules:document.querySelector('link[rel=stylesheet]').sheet.cssRules.length};
})()`);
await cdp('Page.reload');
await new Promise(resolve => setTimeout(resolve, 1200));
const afterReload = await evaluate(`({theme:document.documentElement.dataset.theme,stored:localStorage.getItem('kotakita.theme.v1'),buttonPressed:document.querySelector('#themeBtn').getAttribute('aria-pressed')})`);
console.log(JSON.stringify({afterToggle:before,afterReload}, null, 2));
if (before.theme !== 'dark' || before.stored !== 'dark' || before.ariaPressed !== 'true' || !before.mapUnchanged || before.cssRules < 50 || afterReload.theme !== 'dark' || afterReload.stored !== 'dark' || afterReload.buttonPressed !== 'true') process.exitCode = 1;
ws.close();

