const targets = await (await fetch('http://127.0.0.1:9222/json/list')).json();
const target = targets.find(t => t.type === 'page' && t.url.includes(':8765'));
if (!target) throw new Error('Kota Kita page not found');
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
let id = 0;
const pending = new Map();
ws.onmessage = event => { const msg = JSON.parse(event.data); if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); } };
async function cdp(method, params = {}) {
  const requestId = ++id;
  const result = new Promise(resolve => pending.set(requestId, resolve));
  ws.send(JSON.stringify({ id: requestId, method, params }));
  const response = await result;
  if (response.error) throw new Error(JSON.stringify(response.error));
  return response.result;
}
async function evaluate(expression) {
  const { result, exceptionDetails } = await cdp('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
  if (exceptionDetails) throw new Error(exceptionDetails.text + ': ' + (exceptionDetails.exception?.description || ''));
  return result.value;
}
await cdp('Page.enable');
await cdp('Page.reload', {ignoreCache:true});
await new Promise(resolve => setTimeout(resolve, 900));
const results = [];
for (const [width,height,mobile] of [[1280,800,false],[360,640,true]]) {
  await cdp('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile,screenWidth:width,screenHeight:height});
  await evaluate(`(()=>{if(!KK.game.state?.started)KK.game.startNew('Tema QA'); KK.game.state.paused=true; return true})()`);
  for (const theme of ['light','dark']) {
    await evaluate(`(()=>{const b=document.querySelector('#themeBtn'); const dark=document.documentElement.dataset.theme==='dark'; if((dark?'dark':'light')!==${JSON.stringify(theme)})b.click(); return true})()`);
    await new Promise(resolve=>setTimeout(resolve,250));
    const metrics=await evaluate(`(()=>{const bar=document.querySelector('#timebar'),r=bar.getBoundingClientRect(),children=[...bar.children].map(e=>{const x=e.getBoundingClientRect();return {id:e.id||e.className,left:+x.left.toFixed(1),right:+x.right.toFixed(1)}});return {viewport:innerWidth,theme:document.documentElement.dataset.theme,timebar:{left:+r.left.toFixed(1),right:+r.right.toFixed(1),width:+r.width.toFixed(1),background:getComputedStyle(bar).backgroundImage},children,documentOverflow:document.documentElement.scrollWidth>innerWidth,barOverflow:children.some(c=>c.left<r.left-1||c.right>r.right+1),topbarBackground:getComputedStyle(document.querySelector('#topbar')).backgroundImage}})()`);
    const shot=await cdp('Page.captureScreenshot',{format:'png',captureBeyondViewport:false});
    const file=`/tmp/opencode/kk-${width}-${theme}.png`;
    await (await import('node:fs/promises')).writeFile(file,Buffer.from(shot.data,'base64'));
    results.push({...metrics,file});
  }
}
console.log(JSON.stringify(results,null,2));
ws.close();

